import { NextRequest, NextResponse } from 'next/server'
import { createClient } from '@supabase/supabase-js'

const TOKEN = 'floria-audit-2026'

const PLANTS = [
  {
    name: 'caña de ámbar',
    file: 'cana-de-ambar.jpg',
    mimeType: 'image/jpeg',
    data: '',
  },
  {
    name: 'canna',
    scientificName: 'canna × generalis',
    file: 'canna-generalis.webp',
    mimeType: 'image/webp',
    data: '',
  },
  {
    name: 'limonero',
    file: 'limonero.jpg',
    mimeType: 'image/jpeg',
    data: '',
  },
]

export async function GET(req: NextRequest) {
  const token = req.nextUrl.searchParams.get('token')
  if (token !== TOKEN) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!
  )

  const results = []

  for (const plant of PLANTS) {
    try {
      // Upload to storage
      const bytes = Buffer.from(plant.data, 'base64')
      const path = `user-photos/${plant.file}`

      // Try to create bucket if not exists
      await supabase.storage.createBucket('plant-images', { public: true }).catch(() => {})

      const { error: uploadError } = await supabase.storage
        .from('plant-images')
        .upload(path, bytes, { contentType: plant.mimeType, upsert: true })

      if (uploadError) {
        results.push({ name: plant.name, error: uploadError.message })
        continue
      }

      const { data: { publicUrl } } = supabase.storage.from('plant-images').getPublicUrl(path)

      // Update plant by common name (case-insensitive)
      const searchName = plant.name
      const { data: plants, error: fetchError } = await supabase
        .from('plants')
        .select('id, common_name, scientific_name')
        .ilike('common_name', searchName)

      if (fetchError || !plants?.length) {
        // Try scientific name
        const sci = plant.scientificName
        if (sci) {
          const { data: plants2 } = await supabase.from('plants').select('id, common_name').ilike('scientific_name', sci)
          if (plants2?.length) {
            await supabase.from('plants').update({ cover_image: publicUrl }).eq('id', plants2[0].id)
            results.push({ name: plant.name, id: plants2[0].id, url: publicUrl, status: 'ok' })
            continue
          }
        }
        results.push({ name: plant.name, error: 'Plant not found', url: publicUrl })
        continue
      }

      await supabase.from('plants').update({ cover_image: publicUrl }).eq('id', plants[0].id)
      results.push({ name: plant.name, id: plants[0].id, url: publicUrl, status: 'ok' })
    } catch (e) {
      results.push({ name: plant.name, error: String(e) })
    }
  }

  return NextResponse.json({ results })
}
